      (ps.length?ps.map(x=>'<article class="post"><span class="av">'+avatar(p)+'</span><div class="grow"><div class="meta"><b>'+esc(p.display_name||'Miembro')+'</b><span>'+ago(x.created_at)+'</span></div>'+(x.content.text?'<p>'+esc(x.content.text)+'</p>':'')+attachment(x)+'</div></article>').join(''):'<p class="empty">Este usuario todavía no ha publicado.</p>');
